.cookie-consent-settings-footer {
  border-top: 1px solid rgba(134, 160, 182, 0.24);
  display: grid;
  gap: 10px;
  margin-top: 22px;
  padding-top: 18px;
}

.cookie-consent-settings-footer .cookie-consent-settings-actions {
  grid-template-columns: 1fr;
  margin: 0;
}

.cookie-consent-settings-footer .cookie-consent-accept, .cookie-consent-secondary-actions button {
  align-items: center;
  border-radius: 9px;
  cursor: pointer;
  display: inline-flex;
  font: inherit;
  font-size: 13px;
  font-weight: 900;
  gap: 8px;
  justify-content: center;
  min-height: 48px;
  padding: 0 16px;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease, transform 150ms ease;
