.cookie-consent-settings-footer .cookie-consent-accept {
  color: #07111b;
  width: 100%;
}

.cookie-consent-settings-footer button svg {
  flex: 0 0 auto;
  height: 18px;
  stroke-width: 2.4;
  width: 18px;
}

.cookie-consent-secondary-actions {
  display: grid;
  gap: 10px;
  grid-template-columns: 1fr 1fr;
}

.cookie-consent-back {
  background: rgba(8, 23, 36, 0.74);
  border: 1px solid rgba(230, 238, 245, 0.72);
  color: #f4f8fb;
}

.cookie-consent-reject {
  background: rgba(255, 92, 92, 0.09);
  border: 1px solid rgba(255, 132, 132, 0.7);
  color: #ffb0b0;
}

.cookie-consent-secondary-actions button:hover {
  border-color: #ff8a1f;
  color: #ffac62;
  transform: translateY(-1px);
}

html[data-theme="light"] body .cookie-consent-settings-footer {
  border-color: #cbd3d7 !important;
