/* About page: editorial marketplace presentation. */
html body main.about-showcase-page {
  --about-accent: #ff6a00;
  --about-bg: #06111c;
  --about-panel: #081827;
  --about-line: rgba(151, 177, 199, 0.24);
  --about-muted: rgba(220, 230, 239, 0.72);
  background:
    radial-gradient(circle at 83% 11%, rgba(17, 83, 126, 0.13), transparent 31%),
    linear-gradient(180deg, #06111c 0%, #071522 100%) !important;
  color: #f7f9fb;
  min-height: 100vh;
  overflow: hidden;
  padding: 0 clamp(20px, 4.5vw, 72px) 48px;
}

html body main.about-showcase-page > :is(
  .about-showcase-hero,
  .about-story,
  .about-showcase-features,
  .about-showcase-numbers,
  .about-quote,
  .about-faq,
  .about-cta
) {
  margin-left: auto;
  margin-right: auto;
  max-width: 1320px;
  width: 100%;
}

html body main.about-showcase-page .about-showcase-hero {
  align-items: center;
  border-bottom: 1px solid var(--about-line);
  display: grid;
  gap: clamp(48px, 7vw, 112px);
  grid-template-columns: minmax(280px, 0.9fr) minmax(510px, 1.1fr);
  min-height: 610px;
  padding: 68px 0 56px;
}

html body main.about-showcase-page :is(.about-showcase-kicker, .about-showcase-section-kicker, .about-marketplace-kicker) {
  color: var(--about-accent) !important;
  display: inline-block;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.035em;
  margin-bottom: 18px;
  text-transform: uppercase;
}

html body main.about-showcase-page .about-showcase-copy h1 {
  color: #f8fafc !important;
  font-size: clamp(48px, 4.45vw, 64px);
  font-weight: 950;
  letter-spacing: -0.055em;
  line-height: 0.98;
  margin: 0;
  max-width: 670px;
}

html body main.about-showcase-page .about-showcase-copy h1 span {
  color: var(--about-accent) !important;
  -webkit-text-fill-color: var(--about-accent) !important;
}

html body main.about-showcase-page .about-showcase-copy > p {
  color: var(--about-muted) !important;
  font-size: 16px;
  line-height: 1.7;
  margin: 26px 0 0;
  max-width: 590px;
}

html body main.about-showcase-page .about-marketplace-panel {
  background:
    radial-gradient(circle at 78% 20%, rgba(19, 80, 121, 0.22), transparent 42%),
    rgba(4, 17, 29, 0.68) !important;
  border: 1px solid rgba(151, 177, 199, 0.34) !important;
  border-radius: 12px;
  box-shadow: 0 28px 80px rgba(0, 0, 0, 0.22);
  min-height: 430px;
  padding: clamp(34px, 4vw, 56px);
}

html body main.about-showcase-page .about-marketplace-panel h2 {
  color: #f8fafc !important;
  font-size: clamp(32px, 3.4vw, 48px);
  font-weight: 900;
  letter-spacing: -0.045em;
  line-height: 1.12;
  margin: 0;
  max-width: 640px;
}

html body main.about-showcase-page .about-marketplace-search {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  margin-top: 44px;
}

html body main.about-showcase-page .about-marketplace-search input {
  background: rgba(3, 13, 23, 0.52) !important;
  border: 1px solid rgba(151, 177, 199, 0.38) !important;
  border-radius: 8px 0 0 8px;
  color: #f8fafc !important;
  font: inherit;
  font-size: 16px;
  min-height: 64px;
  min-width: 0;
  outline: none;
  padding: 0 22px;
}

html body main.about-showcase-page .about-marketplace-search input::placeholder {
  color: rgba(219, 229, 238, 0.69) !important;
  opacity: 1;
}

html body main.about-showcase-page .about-marketplace-search input:focus {
  border-color: var(--about-accent) !important;
  box-shadow: inset 0 0 0 1px var(--about-accent);
}

html body main.about-showcase-page .about-marketplace-search button {
  background: linear-gradient(135deg, #ff7d12, #ff5c00) !important;
  border: 0;
  border-radius: 0 8px 8px 0;
  color: #fff !important;
  cursor: pointer;
  font: inherit;
  font-size: 16px;
  font-weight: 900;
  min-width: 112px;
  padding: 0 24px;
}

html body main.about-showcase-page .about-marketplace-categories {
  display: grid;
  gap: 16px;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin-top: 30px;
}

html body main.about-showcase-page .about-marketplace-categories a {
  align-items: center;
  background: rgba(7, 22, 35, 0.7) !important;
  border: 1px solid rgba(151, 177, 199, 0.34) !important;
  border-radius: 8px;
  color: #f5f8fb !important;
  display: flex;
  font-size: 16px;
  font-weight: 800;
  justify-content: center;
  min-height: 70px;
  padding: 14px 12px;
  text-align: center;
  text-decoration: none;
}

html body main.about-showcase-page .about-marketplace-categories a:hover {
  border-color: var(--about-accent) !important;
  color: var(--about-accent) !important;
}

html body main.about-showcase-page .about-marketplace-actions {
  color: #f7f9fb !important;
  display: block;
  font-size: 17px;
  letter-spacing: 0.09em;
  margin-top: 34px;
  text-align: center;
  text-transform: uppercase;
  word-spacing: 0.5em;
}

html body main.about-showcase-page .about-story {
  border-bottom: 1px solid var(--about-line);
  padding: 56px 0 62px;
}

html body main.about-showcase-page .about-story h2, html body main.about-showcase-page :is(.about-showcase-features, .about-showcase-numbers, .about-faq, .about-cta) h2 {
  color: #f8fafc !important;
  font-size: clamp(30px, 3.4vw, 46px);
  font-weight: 900;
  letter-spacing: -0.035em;
  line-height: 1.1;
  margin: 0;
}

html body main.about-showcase-page .about-story-copy {
  display: grid;
  gap: 26px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-top: 28px;
  max-width: 1020px;
}

html body main.about-showcase-page .about-story-copy p {
  color: var(--about-muted) !important;
  font-size: 15px;
  line-height: 1.8;
  margin: 0;
}

html body main.about-showcase-page .about-showcase-features {
  border-bottom: 1px solid var(--about-line);
  border-top: 0;
  padding: 58px 0 64px;
  text-align: center;
}

html body main.about-showcase-page .about-showcase-card-grid {
  display: grid;
  gap: 18px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-top: 34px;
  text-align: left;
}

html body main.about-showcase-page .about-showcase-card {
  background: linear-gradient(180deg, rgba(11, 29, 44, 0.95), rgba(7, 21, 34, 0.95)) !important;
  border: 1px solid rgba(151, 177, 199, 0.28) !important;
  border-radius: 8px;
  box-shadow: none !important;
  min-height: 245px;
  padding: 26px 24px 24px;
}

html body main.about-showcase-page .about-showcase-card::after {
  background: var(--about-accent);
  height: 2px;
  margin-top: 28px;
  width: 36px;
}

html body main.about-showcase-page .about-showcase-card-number {
  color: var(--about-accent) !important;
  display: block;
  font-size: 30px;
  font-weight: 500;
  line-height: 1;
}

html body main.about-showcase-page .about-showcase-card h3 {
  color: #f8fafc !important;
  font-size: 18px;
  margin: 25px 0 12px;
}

html body main.about-showcase-page .about-showcase-card p {
  color: var(--about-muted) !important;
  font-size: 14px;
  line-height: 1.65;
}

html body main.about-showcase-page .about-showcase-numbers {
  border-bottom: 1px solid var(--about-line);
  padding: 54px 0 48px;
  text-align: center;
}

html body main.about-showcase-page .about-showcase-number-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin: 32px 0 0;
}

html body main.about-showcase-page .about-showcase-number {
  border-right: 1px solid var(--about-line);
  min-height: 102px;
  padding: 10px 22px;
}

html body main.about-showcase-page .about-showcase-number strong {
  color: var(--about-accent) !important;
  font-size: clamp(28px, 3vw, 40px);
}

html body main.about-showcase-page .about-showcase-number span {
  color: var(--about-muted) !important;
  font-size: 14px;
  max-width: 180px;
}

html body main.about-showcase-page .about-quote {
  align-items: center;
  border-bottom: 1px solid var(--about-line);
  display: grid;
  gap: 36px;
  grid-template-columns: 120px minmax(0, 760px);
  justify-content: center;
  margin-bottom: 0;
  margin-top: 0;
  padding: 44px 0 48px;
}

html body main.about-showcase-page .about-quote > span {
  color: var(--about-accent) !important;
  font-family: Georgia, serif;
  font-size: 122px;
  font-weight: 900;
  height: 82px;
  line-height: 1;
}

html body main.about-showcase-page .about-quote p {
  color: #eef3f7 !important;
  font-size: clamp(17px, 1.7vw, 22px);
  font-style: italic;
  line-height: 1.55;
  margin: 0;
}

html body main.about-showcase-page .about-quote cite {
  color: var(--about-accent) !important;
  display: block;
  font-size: 13px;
  font-style: normal;
  font-weight: 900;
  margin-top: 14px;
}

html body main.about-showcase-page .about-faq {
  border-bottom: 1px solid var(--about-line);
  padding: 54px 0 58px;
}

html body main.about-showcase-page .about-faq-list {
  display: grid;
  gap: 10px;
  margin-top: 24px;
}

html body main.about-showcase-page .about-faq-item {
  align-items: center;
  background: rgba(7, 22, 35, 0.68) !important;
  border: 1px solid rgba(151, 177, 199, 0.3) !important;
