  font-size: 27px;
  line-height: 1.2;
}

html body main.about-showcase-page .about-faq-item h3 {
  color: #f8fafc !important;
  font-size: 17px;
  margin: 0 0 5px;
}

html body main.about-showcase-page .about-faq-item p {
  color: var(--about-muted) !important;
  font-size: 14px;
  line-height: 1.55;
  margin: 0;
}

html body main.about-showcase-page .about-cta {
  align-items: center;
  border: 1px solid rgba(255, 106, 0, 0.68) !important;
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  margin-top: 34px;
  padding: 34px 22px;
  text-align: center;
}

html body main.about-showcase-page .about-cta h2 {
  font-size: clamp(27px, 3vw, 39px);
